async (page) => {
  // Create a test file and upload it
  const buffer = Buffer.from(
    "MASTER SERVICE AGREEMENT\n\nSection 1: Payment Terms\nCustomer shall pay net 30.\n\nSection 2: Liability\nVendor liability capped at 3 months fees.\n\nSection 3: Termination\n60 days written notice."
  );

  // Set the file on the input
  const fileInput = await page.locator('input[type="file"]');
  await fileInput.setInputFiles({
    name: 'test_contract.txt',
    mimeType: 'text/plain',
    buffer: buffer,
  });

  // Wait a moment for the file to be set
  await page.waitForTimeout(500);

  // Take screenshot showing file selected
  await page.screenshot({ path: 'docs/agentic-eval-pipeline/verify/phase5-file-selected.png' });

  // Click evaluate
  await page.getByRole('button', { name: /evaluate/i }).click();

  // Wait for streaming to start (status text or loading indicator)
  await page.waitForTimeout(3000);
  await page.screenshot({ path: 'docs/agentic-eval-pipeline/verify/phase5-streaming-start.png' });

  // Wait longer for evaluation to progress
  await page.waitForTimeout(15000);
  await page.screenshot({ path: 'docs/agentic-eval-pipeline/verify/phase5-streaming-progress.png' });

  // Wait for completion or timeout
  await page.waitForTimeout(30000);
  await page.screenshot({ path: 'docs/agentic-eval-pipeline/verify/phase5-streaming-final.png' });

  return page.url();
}

