1	"use client";
2	
3	import { useState, useRef, useEffect } from "react";
4	import { useRouter } from "next/navigation";
5	import { FileDropZone } from "@/app/evaluate-contract/FileDropZone";
6	import { LoadingShimmer } from "@/app/evaluate-contract/LoadingShimmer";
7	import {
8	  BACKEND_URL,
9	  POLL_INTERVAL,
10	  POLL_TIMEOUT,
11	  STATUS_TEXT,
12	} from "@/app/evaluate-contract/constants";
13	import {
14	  UploadResponseSchema,
15	  ReviewResponseSchema,
16	} from "@/app/evaluate-contract/types";
17	import { getFailureMessage } from "@/app/evaluate-contract/failure-messages";
18	import { readNDJSONStream } from "@/app/evaluate-contract/stream";
19	import type { StreamClause } from "@/app/evaluate-contract/stream-types";
20	
21	const ERROR_ALERT =
22	  "flex gap-3 rounded-lg border border-egregious-border bg-egregious-bg p-4 text-sm text-egregious-fg";
23	
24	async function uploadContract(
25	  file: File,
26	  instructions: string,
27	  signal: AbortSignal,
28	  stream = false,
29	) {
30	  const form = new FormData();
31	  form.append("file", file);
32	  if (instructions.trim()) form.append("instructions", instructions);
33	  const url = stream
34	    ? `${BACKEND_URL}/api/contracts/upload?stream=true`
35	    : `${BACKEND_URL}/api/contracts/upload`;
36	  const res = await fetch(url, {
37	    method: "POST",
38	    body: form,
39	    signal,
40	  });
41	  if (!res.ok) {
42	    if (res.status === 413) throw new Error("File too large (max 10MB)");
43	    if (res.status === 400) {
44	      const data = await res.json();
45	      throw new Error(data.detail || "Invalid file");
46	    }
47	    throw new Error("Upload failed");
48	  }
49	  return UploadResponseSchema.parse(await res.json());
50	}
51	
52	async function pollReview(
53	  reviewId: string,
54	  signal: AbortSignal,
55	  onStatus?: (s: string) => void,
56	) {
57	  const start = Date.now();
58	  while (Date.now() - start < POLL_TIMEOUT) {
59	    const res = await fetch(`${BACKEND_URL}/api/reviews/${reviewId}`, {
60	      signal,
61	    });
62	    if (!res.ok) throw new Error("Failed to check review status");
63	    const data = ReviewResponseSchema.parse(await res.json());
64	    if (data.status === "completed" || data.status === "failed") return data;
65	    onStatus?.(data.status);
66	    await new Promise((r) => setTimeout(r, POLL_INTERVAL));
67	  }
68	  throw new Error("Evaluation timed out — please try again");
69	}
70	
71	async function consumeStream(
72	  contractId: string,
73	  reviewId: string,
74	  signal: AbortSignal,
75	  callbacks: {
76	    onStatus: (s: string) => void;
77	    onClause: (c: StreamClause) => void;
78	    onSummary: (s: string) => void;
79	  },
80	): Promise<{ navigateTo?: string; error?: string }> {
81	  const res = await fetch(`${BACKEND_URL}/api/reviews/${reviewId}/stream`, {
82	    signal,
83	  });
84	  if (!res.ok) throw new Error("Stream unavailable");
85	
86	  let summaryBuffer = "";
87	
88	  for await (const event of readNDJSONStream(res)) {
89	    if (signal.aborted) return {};
90	
91	    switch (event.event) {
92	      case "started":
93	        callbacks.onStatus("Evaluating contract...");
94	        summaryBuffer = event.summary;
95	        callbacks.onSummary(event.summary);
96	        break;
97	      case "verifying":
98	        callbacks.onStatus("Verifying document...");
99	        break;
100	      case "splitting":
101	        callbacks.onStatus(
102	          `Splitting ${event.agreement_type} into ${event.clause_count} clauses...`,
103	        );
104	        break;
105	      case "token":
106	        if (event.field === "summary") {
107	          summaryBuffer += event.text;
108	          callbacks.onSummary(summaryBuffer);
109	        }
110	        callbacks.onStatus("Evaluating contract...");
111	        break;
112	      case "clause_evaluated":
113	        callbacks.onClause(event.clause);
114	        break;
115	      case "replace":
116	        if (event.field === "summary" && event.text !== undefined) {
117	          summaryBuffer = event.text;
118	          callbacks.onSummary(event.text);
119	        }
120	        break;
121	      case "completed":
122	        return { navigateTo: `/contract/${contractId}` };
123	      case "rejected":
124	        return { error: event.reason };
125	      case "failed":
126	        return { error: event.reason };
127	      case "clause_error":
128	        // Individual clause errors are non-fatal
129	        break;
130	    }
131	  }
132	
133	  return {};
134	}
