136	export default function EvaluateContractPage() {
137	  const [file, setFile] = useState<File | null>(null);
138	  const [instructions, setInstructions] = useState("");
139	  const [isLoading, setIsLoading] = useState(false);
140	  const [error, setError] = useState<string | null>(null);
141	  const [statusText, setStatusText] = useState("Preparing evaluation...");
142	  const [streamClauses, setStreamClauses] = useState<StreamClause[]>([]);
143	  const [streamSummary, setStreamSummary] = useState("");
144	  const router = useRouter();
145	  const controllerRef = useRef<AbortController | null>(null);
146	
147	  useEffect(() => {
148	    return () => controllerRef.current?.abort();
149	  }, []);
150	
151	  async function handleSubmit() {
152	    if (!file) return;
153	    controllerRef.current?.abort();
154	    const controller = new AbortController();
155	    controllerRef.current = controller;
156	    setError(null);
157	    setIsLoading(true);
158	    setStatusText("Preparing evaluation...");
159	    setStreamClauses([]);
160	    setStreamSummary("");
161	
162	    try {
163	      // Upload with stream flag
164	      const { contract_id, review_id } = await uploadContract(
165	        file,
166	        instructions,
167	        controller.signal,
168	        true,
169	      );
170	
171	      // Try streaming first
172	      try {
173	        const result = await consumeStream(
174	          contract_id,
175	          review_id,
176	          controller.signal,
177	          {
178	            onStatus: setStatusText,
179	            onClause: (c) => setStreamClauses((prev) => [...prev, c]),
180	            onSummary: setStreamSummary,
181	          },
182	        );
183	
184	        if (result.navigateTo) {
185	          router.push(result.navigateTo);
186	          return;
187	        }
188	        if (result.error) {
189	          setError(result.error);
190	          setIsLoading(false);
191	          return;
192	        }
193	      } catch {
194	        // Stream failed — fall back to polling with same review_id
