  const uploadResponse = {
    contract_id: "452be08b-a29d-402f-8f44-6b1a0f976efa",
    review_id: "a9198839-1da3-4fb3-ac30-c462cc81ee4e",
    status: "pending",
  };
  const streamBody = [
    JSON.stringify({ event: "started", review_id: uploadResponse.review_id, summary: "", call_to_action: [] }),
    JSON.stringify({ event: "failed", reason: "An error occurred during contract evaluation. Please try again." }),
  ].join("\n") + "\n";

  let callCount = 0;
  await stageFileAndSubmit(() => {
    callCount++;
    if (callCount === 1) {
      return Promise.resolve(
        new Response(JSON.stringify(uploadResponse), { status: 201 }),
      );
    }
    return Promise.resolve(
      new Response(streamBody, { status: 200, headers: { "content-type": "application/x-ndjson" } }),
    );
  });

  await waitFor(() => {
    expect(screen.getByText(/error occurred/i)).toBeInTheDocument();
  });
});

