async (page) => {
  // Dismiss any file chooser dialogs
  page.on('filechooser', async (chooser) => { await chooser.setFiles([]); });
  await page.goto('http://localhost:3000');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: 'docs/agentic-eval-pipeline/verify/current-home.png' });

  // Navigate to a completed contract result
  const firstCard = await page.locator('a[href*="/contract/"]').first();
  if (await firstCard.count() > 0) {
    await firstCard.click();
    await page.waitForTimeout(2000);
    await page.screenshot({ path: 'docs/agentic-eval-pipeline/verify/current-results.png' });
    await page.screenshot({ path: 'docs/agentic-eval-pipeline/verify/current-results-full.png', fullPage: true });
  }
  return 'done';
}

