@import "tailwindcss";

:root {
  --background: #fafaf9;
  --foreground: #1c1917;
  --muted: #78716c;
  --border: #e7e5e4;
  --surface: #ffffff;
  --fair-fg: #15803d;
  --fair-bg: #f0fdf4;
  --fair-border: #bbf7d0;
  --unfair-fg: #a16207;
  --unfair-bg: #fefce8;
  --unfair-border: #fef08a;
  --egregious-fg: #b91c1c;
  --egregious-bg: #fef2f2;
  --egregious-border: #fecaca;
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #0c0a09;
    --foreground: #e7e5e4;
    --muted: #a8a29e;
    --border: #292524;
    --surface: #1c1917;
    --fair-fg: #4ade80;
    --fair-bg: #052e16;
    --fair-border: #14532d;
    --unfair-fg: #facc15;
    --unfair-bg: #422006;
    --unfair-border: #713f12;
    --egregious-fg: #f87171;
    --egregious-bg: #450a0a;
    --egregious-border: #7f1d1d;
  }
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-border: var(--border);
  --color-surface: var(--surface);
  --color-fair-fg: var(--fair-fg);
  --color-fair-bg: var(--fair-bg);
  --color-fair-border: var(--fair-border);
  --color-unfair-fg: var(--unfair-fg);
  --color-unfair-bg: var(--unfair-bg);
  --color-unfair-border: var(--unfair-border);
  --color-egregious-fg: var(--egregious-fg);
  --color-egregious-bg: var(--egregious-bg);
  --color-egregious-border: var(--egregious-border);
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes shimmer-bg {
  0%,
  100% {
    background-color: var(--background);
  }
  50% {
    background-color: color-mix(in srgb, var(--background) 92%, var(--foreground));
  }
}

.streaming-bg {
  animation: shimmer-bg 2s ease-in-out infinite;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), Arial, Helvetica, sans-serif;
}
